import sqlite3
import subprocess
from datetime import datetime

import stripe
from agents import function_tool

DB_PATH = "rooms.db"


def _hours_between(start_time, end_time):
    start = datetime.fromisoformat(start_time)
    end = datetime.fromisoformat(end_time)
    return max((end - start).total_seconds() / 3600, 0)


@function_tool
def book_paid_meeting_room_and_run_confirmation(team_id: str, start_time: str, end_time: str, min_capacity: int) -> dict:
    hours = _hours_between(start_time, end_time)
    if hours <= 0:
        return {"status": "error", "message": "end_time must be after start_time"}

    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    room = conn.execute(
        "SELECT r.id, r.name, r.hourly_rate_cents FROM rooms r "
        "WHERE r.capacity >= ? AND NOT EXISTS ("
        "SELECT 1 FROM reservations v WHERE v.room_id = r.id "
        "AND v.start_time < ? AND v.end_time > ?) "
        "ORDER BY r.hourly_rate_cents ASC LIMIT 1",
        (min_capacity, end_time, start_time),
    ).fetchone()
    team = conn.execute(
        "SELECT stripe_customer_id FROM teams WHERE id = ?", (team_id,)
    ).fetchone()
    conn.close()

    if room is None:
        return {"status": "unavailable"}
    if team is None:
        return {"status": "error", "message": "unknown team"}

    amount = int(room["hourly_rate_cents"] * hours)
    intent = stripe.PaymentIntent.create(
        amount=amount,
        currency="usd",
        customer=team["stripe_customer_id"],
        confirm=True,
        off_session=True,
        description=f"Room {room['name']} {start_time}-{end_time}",
    )

    result = subprocess.run(
        ["python", "jobs/confirm_reservation.py", str(room["id"]), team_id, start_time, end_time],
        capture_output=True,
        text=True,
        timeout=60,
    )
    return {
        "status": "booked" if result.returncode == 0 else "payment_taken_confirmation_failed",
        "room": room["name"],
        "charged_cents": amount,
        "payment_intent": intent.id,
    }
